import type { User } from "./generated/User";

type LegacyUser = User & { name?: string };

export function UserCard({ user }: { user: LegacyUser }) {
  const label = user.displayName ?? user.name ?? "Unknown";
  return <img src={user.avatarUrl} />;
}
